"""fig1 — generated by sf_init.py.

Claim: see contracts/fig1.yaml
Style: nature (89 mm single column)

Rules that pay off immediately:
  * read data from a file, never inline arrays
  * seed every RNG so reruns match
  * apply the style ONCE, here at the top
  * save a review PNG alongside the vector output
"""
import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt
import numpy as np
from pathlib import Path

# Styles live two levels up, inside the skill bundle. Resolve relative to this file so
# the example runs from a fresh clone on any machine.
STYLE_DIR = Path(__file__).resolve().parents[2] / "styles"
plt.style.use([STYLE_DIR / "base.mplstyle", STYLE_DIR / "nature.mplstyle"])

MM = 1 / 25.4
OUT = Path(__file__).parent
OUT.mkdir(parents=True, exist_ok=True)

# --- data -----------------------------------------------------------------
# Replace with a real read; the seeded fallback keeps the scaffold runnable.
# df = pd.read_csv(Path('data/processed/input.csv'))
rng = np.random.default_rng(0)
x = np.linspace(0, 10, 24)
y = np.sin(x / 2) + rng.normal(0, 0.05, x.size)
lo, hi = y - 0.15, y + 0.15

# --- figure ---------------------------------------------------------------
fig, ax = plt.subplots(figsize=(89 * MM, 64.1 * MM))

ax.plot(x, y, "o-", label="Measurement (N=24)")
ax.fill_between(x, lo, hi, alpha=0.25, linewidth=0, label="95% CI")

ax.set_xlabel("Time $t$ (s)")
ax.set_ylabel("Amplitude $A$ (V)")
ax.legend(loc="upper right")

# --- export ---------------------------------------------------------------
for ext in ("pdf", "svg", "png"):
    fig.savefig(OUT / f"fig1.{ext}", dpi=300)
print(f"saved {OUT}/fig1.*")
